query.transform:
store.lines = store.lines or {}
table.insert(store.lines, 1, { at = os.date("%H:%M:%S"), stream = stream, line = rs })
while #store.lines > 10 do table.remove(store.lines) end
return { columns = { "at", "stream", "line" }, rows = vim.tbl_map(function(l)
  return { l.at, l.stream, l.line }
end, store.lines) }

-- rs: one event (decoded and checked); params: the request's parameters.
store.events = store.events or {}
table.insert(store.events, 1, { os.date("%H:%M:%S"), params.path.source, rs.user, rs.action })
while #store.events > 10 do table.remove(store.events) end
return { columns = { "at", "source", "user", "action" }, rows = store.events }
